    { t: "堵不如疏", d: "鲧堵水而败，禹疏水而成。对洪水如此，对市场情绪、组织矛盾、家庭沟通也如此——压制只会积蓄势能，疏导才能化解。这是中国最古老的管理智慧。" },
    { t: "组织公共事务的人，最终掌握权力", d: "禹的王权来自治水——大工程需要动员和协调，动员和协调就是权力本身。看懂'谁在组织资源'，往往比看谁头衔大更接近真相。" },
    { t: "基本盘比规模重要", d: "少康凭一成一旅复国：地盘可以小，但队伍要是自己的。做投资留本金，做事业留核心团队，做人留信用——翻盘靠的从来不是巅峰期的规模。" },
    { t: "把'很可能'和'确定'分开", d: "二里头很可能是夏都，但学界坚持不说死——证据不足时保留分寸，是专业精神。听到任何斩钉截铁的结论，先问一句：证据到哪一级了？" }
