  title: "楚汉相争与文景之治",
  kicker: "前 206 — 前 141 · 从废墟到粮仓",
  body: `
<p>秦末天下大乱时，沛县有个四十八岁的亭长——大致相当于乡镇派出所长——押送刑徒去骊山，路上人跑了一半。按秦法这是死罪，他索性把剩下的人全放了："你们都走吧，我也跑路了。"有十几个壮士愿意跟着他。这个中年失业的基层公务员叫刘邦，爱喝酒，爱吹牛，看见秦始皇车驾时说过一句"大丈夫当如此也"。</p>
<p>同一时刻，江东有个二十出头的贵族子弟看到同样的车驾，说的是："彼可取而代也。"他叫项羽，力能扛鼎，是楚国名将之后。两句话，两种性格，四年楚汉之争的结局，几乎已经写在里面了。</p>
<h2>会用人的，赢了会打仗的</h2>
<p>灭秦之战中，项羽是无可争议的战神：巨鹿之战破釜沉舟，九战九捷，诸侯将领跪着进他的辕门不敢抬头。刘邦则抢先入了关中，与百姓"约法三章"：杀人者死，伤人及盗抵罪——秦朝的严刑苛法一夜废除，关中人心尽归。鸿门宴上，项羽本可一举除掉刘邦，却在犹豫中放虎归山；范增气得断言："夺项王天下者，必沛公也。"</p>
<p>此后四年，刘邦正面战场几乎逢项羽必败，却总能翻盘。奥秘他自己总结过，堪称史上最著名的复盘："运筹帷幄之中，决胜千里之外，吾不如张良；镇国家、抚百姓、给馈饷，吾不如萧何；连百万之军，战必胜，攻必取，吾不如韩信。此三者，皆人杰也，<strong>吾能用之，此吾所以取天下也。</strong>项羽有一范增而不能用，此其所以为我擒也。"韩信早年受过胯下之辱，在项羽帐下只是执戟郎，转投刘邦后被萧何月下追回、登坛拜将，随后明修栈道暗度陈仓、背水一战、十面埋伏——楚汉的天平，正是被这个项羽看不上的人压垮的。</p>
<p>公元前 202 年，垓下。楚军被围，夜闻四面楚歌，军心涣散。项羽突围至乌江，亭长劝他渡江再起，他笑答：当年带八千江东子弟渡江，今无一人还，"纵江东父兄怜而王我，我何面目见之？"自刎，年三十一。李清照后来为他写下"至今思项羽，不肯过江东"——败得漂亮，是另一种流传千古的方式。</p>
<h2>功臣的下场与白登的教训</h2>
<p>刘邦称帝后的剧本，后世帝王抄了两千年：异姓王一个个被清洗。韩信被吕后诱杀于长乐宫钟室，临死叹"狡兔死，走狗烹"；当年力荐他的萧何，正是设局者之一——"成也萧何，败也萧何"由此而来。对外则碰了硬钉子：前 200 年刘邦亲征匈奴，在白登山被四十万骑兵围了七天，靠贿赂单于阏氏才脱身。汉朝就此认清现实：打不过，先和亲——<strong>屈辱，但为国家买来了七十年喘息。</strong></p>
<h2>无为而治：政府少折腾的红利</h2>
<p>刘邦死后，吕后专权、诸吕之乱，宫廷血雨腥风；但对民间，汉初的国策始终稳定：轻徭薄赋，与民休息。文帝把田租降到三十税一（收成的 3.3%，中国古代最低纪录之一），想修个露台，一算要花"十家之产"，作罢；他在位二十三年，宫室园林没有增添。缇萦上书救父，文帝为之废除肉刑。景帝时七国之乱爆发——诸侯坐大，晁错建议削藩，七国以"清君侧、诛晁错"为名造反，景帝慌乱中腰斩了晁错，叛军却并不退兵（"清君侧"从来只是借口，这个剧本一千五百年后的朱棣还会再用）——最终周亚夫三个月平叛，中央集权反而因祸得福地巩固了。</p>
<p>七十年不折腾的结果，《史记》写得让人咋舌：京师的钱堆积亿万，穿钱的绳子朽烂得没法数；太仓的粮食陈粮压着陈粮，溢到仓外露天堆放，多到腐烂不可食。<strong>一个从废墟起步的王朝，靠"少收税、少征役、少干预"攒出了中国古代第一个盛世。</strong>这笔巨额储蓄有什么用？它的孙子汉武帝很快会给出答案——也会给出代价。</p>
`,
