  title: "东晋：衣冠南渡与淝水之战",
  kicker: "317 — 420 · 半壁江山如何守住百年",
  body: `
<p>南渡之初，流亡的士大夫们常在建康城外的新亭聚会。有一次宴饮，周顗望着江景叹息："风景不殊，正自有山河之异！"——风景没变，山河却换了主人。满座相视流泪。丞相王导脸色一变，说出了那句提振了一个时代的话：<strong>"当共戮力王室，克复神州，何至作楚囚相对！"</strong>——正该同心协力光复中原，怎么能像囚徒一样相对哭泣！</p>
<p>一句话止住了集体的眼泪。流亡政权最缺的不是兵和钱，是不认输的精气神——王导深谙此道。</p>
<h2>王与马，共天下</h2>
<p>317 年，晋室宗亲司马睿在建康（今南京）重建晋朝。这位皇帝在江东毫无根基，全靠琅琊王氏兄弟撑场：王导在朝中调和南北士族，王敦在长江上游握着兵权。登基大典上，司马睿竟拉着王导同升御座——王导赶紧辞让，但"王与马，共天下"的格局已是公开的事实。<strong>东晋一朝，皇权始终是弱势的：王、庾、桓、谢几大家族轮流执政，皇帝更像董事会推举的名誉董事长。</strong>这套"门阀共治"先天不稳，却也意外地形成了权力制衡，让半壁江山在强敌环伺下维持了一百年。</p>
<p>北伐的火种一直没灭。将军祖逖当年与好友刘琨同被而眠，半夜听到鸡叫，踢醒刘琨："此非恶声也！"起身舞剑——"闻鸡起舞"就是他们。渡江北伐时，祖逖在江心敲着船楫发誓：不清中原而复济者，有如大江！他招募流民、收复黄河以南大片失地，朝廷却猜忌掣肘、不给后援，祖逖忧愤而死，收复的土地得而复失。<strong>东晋的北伐大多如此：不怕敌人强，就怕自家朝廷怕你赢——功高震主的将军，比失地更让门阀们恐惧。</strong></p>
<h2>投鞭断流的赌局</h2>
<p>与此同时，北方在血火中走马灯般换了一轮又一轮政权，最终由氐族建立的前秦统一。天王苻坚是五胡君主里少见的雄才：重用汉人王猛治国，劝课农桑、整肃吏治，北方一度重现治世气象。王猛临终留下遗言：晋虽偏居江南，却是正朔所在、上下安和，<strong>切勿伐晋</strong>；心腹之患是鲜卑、羌人这些刚归附的势力。</p>
<p>苻坚没听。383 年，他征发各族大军号称八十七万南下，豪言："以吾之众旅，投鞭于江，足断其流！"——我的大军把马鞭扔进长江，都能截断江流。东晋方面，宰相谢安派弟弟谢石、侄子谢玄率八万"北府兵"迎战——这支由南渡流民组成的军队，是东晋最能打的部队。</p>
<p>决战在淝水岸边。晋军隔水请求：贵军稍退，让我军渡河决战。苻坚打的算盘是半渡而击，下令后撤——<strong>他忘了自己的大军是几十个民族拼凑的，人心各异，一退就收不住了。</strong>此前被俘的晋将朱序趁乱在阵后大喊："秦兵败矣！"后军不明就里，转身就跑，践踏成山。晋军趁势掩杀，前秦大军一溃千里，逃兵听到风声鹤唳都以为是追兵，看到八公山上的草木都以为是晋军——"风声鹤唳、草木皆兵"由此而来。</p>
<p>捷报送到建康时，谢安正在与客人下棋。他扫了一眼，随手放在一边，继续落子。客人忍不住问，他淡淡答："小儿辈遂已破贼。"——孩子们已经把敌人打垮了。客人走后，他起身回内室，过门槛时激动得把木屐的齿都碰断了而不自知。<strong>人前的云淡风轻是演的——但在恐慌可以传染的时刻，领导者的镇定本身就是战略资源，演，也是职责的一部分。</strong></p>
<h2>之后</h2>
<p>淝水之战以八万胜八十余万（号称），保住了江南百年基业，也保住了南渡以来积蓄的华夏文脉。前秦则一夜崩盘：慕容鲜卑、羌人相继反叛复国，正应了王猛的遗言，苻坚两年后被昔日部下缢杀——一场本可不打的战争，赔光了一生的功业。</p>
<p>东晋的暮年，则败给了自己人：门阀内斗、桓玄篡位、孙恩起义，最终出身北府兵的寒门武人刘裕收拾残局，420 年代晋自立，国号宋。门阀的时代开始落幕，南北朝拉开帷幕。而这一百年偏安里，江南从蛮荒泽国被垦成鱼米之乡，书圣王羲之在会稽写下《兰亭集序》，陶渊明种豆南山写下"采菊东篱下"——<strong>政治上憋屈的时代，文化上却熠熠生辉；乱世夺走了中原，也逼出了江南。</strong></p>
`,
