  title: "隋朝：再造统一与大运河",
  kicker: "581 — 618 · 一个像秦朝的王朝",
  body: `
<p>公元 618 年春，江都（扬州）行宫。五十岁的隋炀帝杨广对着镜子端详良久，回头对萧后说了一句让史官记录千年的话："好头颈，谁当斫之？"——这么好的头颅，会是谁来砍下它呢？几天后，他的禁卫军哗变，昔日宠臣宇文化及带兵闯入，杨广被用一条练巾缢死。他到死都保持着体面：天子自有死法，不可加刃——但没人在意了。</p>
<p>一个统一了三百年分裂、修出千年运河、开创科举雏形的王朝，为什么三十八年就走到这一步？隋朝的故事，处处像三百年前秦朝的回声。</p>
<h2>开皇：被低估的盛世</h2>
<p>581 年，北周外戚杨坚受禅建隋；589 年挥师灭陈，自西晋末年以来近三百年的分裂重归一统。隋文帝杨坚可能是中国历史上存在感与功绩最不成比例的皇帝：他创立<strong>三省六部制</strong>——中书省起草、门下省审核、尚书省执行，六部分工明确，这套中央官制的骨架一直用到清末；他简化地方行政为州县两级，裁汰冗官；下令清查户口（"大索貌阅"），把豪强隐匿的人口挖出来编入国家户籍，纳税人口暴增；广建义仓防灾备荒。他本人节俭到近乎抠门，一次想赏功臣，府库竟因布帛太多堆不下而放在廊下。开皇年间户口从四百万户涨到八百九十万户——<strong>史称"开皇之治"，其富庶程度，唐朝立国几十年后仍在吃隋朝粮仓的老本（唐初名臣感叹隋储备"得供五六十年"，此说见于《贞观政要》，数字或有夸张）。</strong></p>
<p>但杨坚晚年在继承人问题上栽了历史级的跟头。太子杨勇性情直率、生活奢纵；次子杨广则把"人设经营"做到了极致：府中乐器蒙尘示不好声色，只与正妻同出同入示不好色，每逢父母使者必亲自迎送厚礼——独孤皇后与文帝渐渐深信次子仁孝俭朴。600 年，杨勇被废，杨广入主东宫。604 年文帝病重，据《隋书》等记载，病榻上的文帝察觉杨广劣迹欲召回杨勇，随即暴崩，杨广即位——弑父之说流传千年，真相已不可考，正史采取的是"暧昧留疑"的笔法，我们也如实存疑。</p>
<h2>大业：把百年工程压进十年</h2>
<p>杨广的年号"大业"暴露了他的自我期许。平心而论，他干的几件大事，单拎出来都配得上"雄才大略"：营建东都洛阳，沟通南北；开凿<strong>大运河</strong>——以洛阳为中心，北抵涿郡（北京），南达余杭（杭州），把海河、黄河、淮河、长江、钱塘江五大水系连成一张水网，全长两千多公里；创设进士科（科举制的开端，学界多系于其年间）；西巡张掖经略西域，重开丝路。</p>
<figure class="fig">
<svg viewBox="0 0 360 520" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="隋大运河示意">
  <rect class="cx-box" x="105" y="16" width="150" height="50" rx="12"/>
  <text class="cx-btxt" x="180" y="38" text-anchor="middle">涿郡（北京）</text>
  <text class="cx-btxt2" x="180" y="56" text-anchor="middle">北端 · 征辽东的基地</text>
  <line class="cx-flow" x1="180" y1="66" x2="180" y2="106"/>
  <text class="cx-lab-a" x="255" y="90" text-anchor="middle">永济渠</text>
  <rect class="cx-box-a" x="105" y="110" width="150" height="54" rx="12"/>
  <text class="cx-btxt" x="180" y="133" text-anchor="middle">洛阳</text>
  <text class="cx-btxt2" x="180" y="152" text-anchor="middle">东都 · 运河中枢</text>
  <line class="cx-flow" x1="180" y1="164" x2="180" y2="204"/>
  <text class="cx-lab-a" x="255" y="188" text-anchor="middle">通济渠</text>
  <rect class="cx-box" x="105" y="208" width="150" height="50" rx="12"/>
  <text class="cx-btxt" x="180" y="230" text-anchor="middle">山阳（淮安）</text>
  <text class="cx-btxt2" x="180" y="248" text-anchor="middle">淮河枢纽</text>
  <line class="cx-flow" x1="180" y1="258" x2="180" y2="298"/>
  <text class="cx-lab-a" x="245" y="282" text-anchor="middle">邗沟</text>
  <rect class="cx-box" x="105" y="302" width="150" height="50" rx="12"/>
  <text class="cx-btxt" x="180" y="324" text-anchor="middle">江都（扬州）</text>
  <text class="cx-btxt2" x="180" y="342" text-anchor="middle">长江枢纽 · 炀帝葬身处</text>
  <line class="cx-flow" x1="180" y1="352" x2="180" y2="392"/>
  <text class="cx-lab-a" x="255" y="376" text-anchor="middle">江南河</text>
  <rect class="cx-box" x="105" y="396" width="150" height="50" rx="12"/>
  <text class="cx-btxt" x="180" y="418" text-anchor="middle">余杭（杭州）</text>
  <text class="cx-btxt2" x="180" y="436" text-anchor="middle">南端 · 江南财赋之地</text>
  <text class="cx-lab" x="180" y="482" text-anchor="middle">四段渠道贯通五大水系，全长两千余公里</text>
  <text class="cx-lab" x="180" y="502" text-anchor="middle">六年完工，役夫数百万</text>
</svg>
<figcaption>大运河：功在千秋的国家动脉，也是压垮当代民力的最后几根稻草之一</figcaption>
</figure>
<p>问题不在做什么，在于<strong>全部同时做，且全靠透支民力。</strong>营洛阳每月役使二百万人；开运河六年征发数百万役夫，监工酷烈，死者相枕；龙舟下江南，纤夫拉船的队伍绵延两岸。压垮骆驼的最后一击是三征高句丽：612 年第一征，动员军队一百一十三万、民夫数倍于此——渡过辽河的三十余万人，生还者不足三千。第二征因杨玄感叛乱中断，第三征草草收场。<strong>十年之内，这个人口四千余万的帝国被征发的人次数以千万计。</strong>山东民谣《无向辽东浪死歌》唱了出来："譬如辽东死，斩头何所伤！"——反正去辽东也是送死，造反被砍头又算什么！</p>
<h2>回声</h2>
<p>611 年起，民变蜂起，豪杰并起百余支；617 年，太原留守李渊起兵；618 年，江都兵变，杨广死于非命。萧瑟的是，他的运河很快开始滋养别人的盛世：唐朝的漕运、宋朝的汴京繁华、直到今天仍在通航的江南河段，全部受益于此。晚唐诗人皮日休写过一首翻案诗："尽道隋亡为此河，至今千里赖通波。若无水殿龙舟事，共禹论功不较多。"——都说隋朝亡在这条河，可千里航运至今仰赖它；若没有龙舟游乐那些荒唐事，论功劳未必输给大禹。</p>
<p>隋与秦的相似度高得惊人：都终结了数百年分裂，都留下了千年制度（郡县制/三省六部与科举），都修了超级工程（长城/运河），都二世而亡，都把家底留给了一个更懂节奏的继任者（汉/唐）。<strong>历史仿佛在重复同一道题：伟大的工程和伟大的暴政，常常是同一件事的两面——区别只在于，账单是分期偿还，还是一次付清。</strong></p>
`,
