<p>十九世纪初的中英贸易，让英国人头疼了几十年：英国人疯狂需要中国的茶叶（伦敦的下午茶已是国民习惯），中国人却几乎不需要英国的任何商品——呢绒卖不动，棉布竞争不过土布。白银像潮水一样单向流入中国。东印度公司最终找到了那件"中国人会上瘾的商品"：<strong>印度种植的鸦片。</strong></p>
